def show_to_dict(text):
    info = {}
    for line in text.splitlines():
        key, _, value = line.partition(':')
        value = value.strip()
        if key == 'Requires':
            value = value.split(', ') if value else []
        info[key] = value
    return info

def missing_packages(required, installed):
    have = {name.lower() for name in installed}
    return [name for name in required if name.lower() not in have]

def check_requirements(req_text, installed):
    report = {'missing': [], 'wrong_version': []}
    for line in req_text.splitlines():
        line = line.strip()
        if not line or line.startswith('#'):
            continue
        name, version = line.split('==')
        have = installed.get(name.lower())
        if have is None:
            report['missing'].append(name)
        elif have != version:
            report['wrong_version'].append(name)
    return report

